#include <cassert>
#include "scenes.h"
#include "src/generation/migration/strong_rhythm_migration.h"
using namespace GroovePuterRhythm;
StrongRhythmMelodicRequestProbe cap(unsigned mode,unsigned address){GenreSettings s{};s.generativeMode=mode;s.recipe=0;s.rhythmSelectionMode=(uint8_t)RhythmSelectionMode::Auto;s.rhythmArchetypeId=kNoArchetypeId;StrongRhythmMigrationContext c{};c.patternAddress=address;c.level=RealizationLevel::P2Variation;c.feelProfile=FeelProfileId::Straight;c.tonalMaterializationEnabled=true;c.scaleTypeValue=kScaleDorian;StrongRhythmMelodicRequestProbe p{};setStrongRhythmMelodicRequestProbe(&p);DrumPatternSet d{};SynthPattern a{},b{};auto r=migrateStrongRhythmMaterial(s,c,d,a,b);setStrongRhythmMelodicRequestProbe(nullptr);assert(p.captured);if(mode==3&&address==7){assert(r.synthBRole==SemanticSynthBRole::Melodic&&r.melodicRhythmId==MelodicRhythmId::DelayedAnswer&&r.motifShapeId==MotifShapeId::CallResponse&&r.phraseBars==4);}if(mode==3&&address==19){assert(r.synthBRole==SemanticSynthBRole::Melodic&&r.melodicRhythmId==MelodicRhythmId::SparseCall&&r.motifShapeId==MotifShapeId::Mirror&&r.phraseBars==4&&r.archetype==(ReferenceVocabulary::Archetype)23&&r.progressionId==(ProgressionId)1);}if(mode==0&&address==0){assert(r.synthBRole==SemanticSynthBRole::Melodic&&r.melodicRhythmId==MelodicRhythmId::RepeatedCell&&r.motifShapeId==MotifShapeId::Pivot&&r.phraseBars==4&&r.archetype==(ReferenceVocabulary::Archetype)7&&r.progressionId==(ProgressionId)1);}return p;}
void replay(const StrongRhythmMelodicRequestProbe&p){for(unsigned i=0;i<4;i++){auto q=p.request;q.barOrdinal=i;assert(q.requestedRhythm==p.request.requestedRhythm&&q.requestedShape==p.request.requestedShape&&q.family==p.request.family&&q.archetypeId==p.request.archetypeId&&q.bassOnsets==p.request.bassOnsets&&q.chordOnsets==p.request.chordOnsets&&q.protectedSpace==p.request.protectedSpace&&q.generation.projectSeed==p.request.generation.projectSeed&&q.generation.phraseOrdinal==p.request.generation.phraseOrdinal&&q.allowEmptyBar==p.request.allowEmptyBar);auto m=realizeMelodicMotif(q);assert(m.status==MelodicMotifStatus::Ok||m.status==MelodicMotifStatus::ValidButEmpty);}}
int main(){auto p3=cap(3,7);auto p1=cap(3,19);auto p2=cap(0,0);replay(p1);replay(p2);replay(p3);return 0;}
